/// 产品里有、接口还没有的功能（技术架构 8.2、8.5），和现状差距 2.1 一一对应。
///
/// 入口照常显示，旁边放「待接入」，点了不发请求。接口上线后从这里删掉一项、接上接口，
/// 再删掉现状差距里对应的一行。是编译期常量而不是远程开关：接口没好时客户端代码也没写。
enum PendingFeature {
  /// 评论、回复、我的评论、全部评论、写评论。
  comments,

  /// 专题、往期专题、菜品详情的专题提示。
  topics,

  /// 举报菜、评论和用户。
  report,

  /// 店铺评价和推荐率。
  shopRating,

  /// 收藏店铺。
  shopFavorite,

  /// 餐厅详情的「信息有误」。
  wrongInfo,

  /// 附近的筛选面板和「推荐率最高」「菜最多」排序。
  nearbyFilter,

  /// 附近按菜名找店。
  nearbyDishSearch,

  /// 「调整照片」的「自动去掉背景」：接口只存开关，后端还没生成去背景的图（技术架构 13.8）。
  removeBackground,
}
